import * as C from './core.js';
import CURRENT_PLAN from './current-plan.js';
const KEY='berias-training-v1',app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let installPrompt=null;
let state,storageError='',view=location.hash.slice(1)||'today',selectedDate,importCandidate=null,timerTick;
try{const raw=localStorage.getItem(KEY);state=raw?C.validateBackup(JSON.parse(raw)):C.initialState(CURRENT_PLAN);}catch(e){storageError='Gespeicherte Daten konnten nicht geladen werden. Nichts wurde überschrieben. Bitte vorhandene Browserdaten sichern oder ein Backup wiederherstellen. '+e.message;state=C.initialState(CURRENT_PLAN);}
selectedDate=C.isoDay(new Date(),state.settings.zone);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=d=>new Intl.DateTimeFormat('de-DE',{dateStyle:'full',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z'));
const number=v=>v===''?null:Number(v);
const nval=n=>n==null?'':Number(n.toFixed(4));
const active=()=>state.sessions.find(s=>s.status==='active');
const today=()=>C.isoDay(new Date(),state.settings.zone);
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(toast.id);toast.id=setTimeout(()=>el.style.display='none',4000);}
function save(){if(storageError){toast('Speichern blockiert: zuerst Datenproblem in Einstellungen lösen.');return false;}try{const disk=localStorage.getItem(KEY);if(disk&&JSON.parse(disk).revision>state.revision){storageError='Ein anderer Tab hat neuere Daten gespeichert. Bitte diese Seite neu laden.';render();return false;}state.revision=(state.revision||0)+1;localStorage.setItem(KEY,JSON.stringify(state));document.querySelector('#saved').textContent='Gespeichert · '+new Date().toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'});return true;}catch(e){storageError='Speichern fehlgeschlagen. Deine Eingaben sind noch hier. Bitte jetzt ein Backup exportieren. '+e.message;document.querySelector('#saved').textContent='Nicht gespeichert';toast(storageError);return false;}}
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=C.validateBackup(JSON.parse(e.newValue));if(next.revision>state.revision){state=next;render();toast('Daten aus anderem Tab aktualisiert.');}}catch{toast('Browserdaten wurden außerhalb dieser Seite verändert.');}}});
function nav(v){view=v;location.hash=v;render();window.scrollTo({top:0,behavior:'smooth'});}
function select(label,name,value,options,attrs=''){return `<label>${label}<select name="${name}" ${attrs}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
function input(label,name,value,type='number',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;}
function modal(title,body,actions=''){dialog.innerHTML=`<div class="row between"><h2>${title}</h2><button data-action="close-dialog" aria-label="Dialog schließen">×</button></div>${body}<div class="dialog-actions"><button data-action="close-dialog">Schließen</button>${actions}</div>`;dialog.showModal();}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));app.innerHTML=(storageError?`<div class="warning">${esc(storageError)} <button data-nav="settings">Backup & Einstellungen</button></div>`:'')+({today:renderToday,training:renderTraining,history:renderHistory,settings:renderSettings,mobility:renderMobility}[view]||renderToday)();updateTimer();}
function renderTodayBase(){const p=C.activePlan(state,selectedDate),slot=C.planned(state,selectedDate),week=C.planWeek(state,selectedDate,p),c=C.checkin(state,selectedDate),r=C.recommendation(state,selectedDate,slot),trip=C.tripAt(state,selectedDate);const preview=slot?C.buildSession(state,selectedDate,slot.key):null;const logged=state.sessions.filter(s=>s.date===selectedDate);const monday=C.addDays(selectedDate,-((new Date(selectedDate+'T12:00:00Z').getUTCDay()+6)%7));return `<div class="row between"><div><div class="eyebrow">${esc(trip?'Deutschland · Reise':state.settings.location)} · Woche ${week} / ${p.weeks}</div><h1>Dein Training heute.</h1></div><label>Trainingstag<input id="selected-date" type="date" value="${selectedDate}"></label></div><div class="week">${Array.from({length:7},(_,i)=>{const d=C.addDays(monday,i),s=C.planned(state,d);return `<button class="day ${d===selectedDate?'current':''} ${state.sessions.some(s=>s.date===d&&['completed','partial'].includes(s.status))?'done':''}" data-date="${d}">${['Mo','Di','Mi','Do','Fr','Sa','So'][i]}<b>${d.slice(8)}</b>${esc(s?.name.replace('Kontrollierte ','').replace('Lange ','')||'Frei')}</button>`;}).join('')}</div><div class="grid"><div><section class="card hero"><div class="row between"><span class="eyebrow">${esc(dateLabel(selectedDate))}</span><span class="badge">${slot?slot.type==='strength'?'KRAFT':'AUSDAUER':'ERHOLUNG'}</span></div><h1>${esc(slot?.name||(week>p.weeks?'Zyklus abgeschlossen':'Heute ist frei.'))}</h1><p class="muted">${preview?preview.cardio?esc(preview.cardio.protocol):'8 min aufwärmen · kontrollierte Sätze · 3–5 min locker ausklingen.':'Keine Einheit nachholen oder verdichten. Bewegung nach Lust und Befinden.'}</p>${preview?`<div class="metrics"><div><strong>${preview.cardio?preview.cardio.plannedMinutes:'35–50'}<small> min</small></strong><span>${preview.cardio?'Geplante Dauer':'Mit Aufwärmen'}</span></div><div><strong>${preview.cardio?'3–4':preview.targetRir}</strong><span>${preview.cardio?'Locker · Anstrengung /10':'Wdh. Reserve'}</span></div></div>`:''}<div class="row">${active()?'<button class="primary" data-nav="training">Training fortsetzen →</button>':slot?`<button class="primary" data-action="start" data-key="${esc(slot.key)}">${logged.some(s=>s.key===slot.key)?'Weiteres Training starten':'Training starten →'}</button>`:'<button class="primary" data-action="start" data-key="extra">Freies Training starten</button>'}<button class="quiet" style="color:white" data-action="choose-session">Andere Einheit</button></div></section><section class="card"><div class="row between"><h2>${preview?.exercises.length?'Deine Übungen':'Dein Rahmen'}</h2><span class="badge">${esc(p.name)}</span></div>${preview?.exercises.length?`<ul class="list">${preview.exercises.map((e,i)=>`<li><div><span class="num">${String(i+1).padStart(2,'0')}</span><b>${esc(e.name)}</b><p class="reason">${esc(e.guidance)}</p></div><span>${e.sets.length} × ${e.min}–${e.max}${e.mode==='time'?' s':e.side?' / Seite':''}</span></li>`).join('')}</ul>`:`<p>${preview?.cardio?esc(preview.cardio.protocol):'Zwei Krafttage, drei Ausdauertage. Freitag und Sonntag bleiben frei.'}</p><p class="reason">${!state.settings.runReady?'Laufverträglichkeit noch nicht bestätigt: Intervalle auf Rad, lange Einheit als Run-Walk.':''} Umfang nur bei guter Verträglichkeit steigern; nicht gleichzeitig Tempo, Laufanteil und Dauer.</p>`}<details><summary>Plan, Reisen & Verschieben</summary><p class="reason">Verpasste Einheiten bleiben als nicht dokumentiert sichtbar. Es gibt kein automatisches Nachholen. Du kannst den heutigen Slot ersetzen oder den Wochenfortschritt bewusst pausieren.</p><div class="row"><button data-action="choose-session">Heutigen Slot ändern</button><button data-action="hold-week">Planwoche 7 Tage verlängern</button><button data-action="recovery-week">7 Tage Wiedereinstieg ab heute</button><button data-action="reset-intervals">Künftige Intervall-Verschiebungen zurücksetzen</button><button data-nav="settings">Reise eintragen</button></div><p><a href="berias-wochenplan-12-wochen.html" target="_blank" rel="noopener">Vollständiger Originalplan ↗</a></p></details>${logged.length?'<h3>Heute dokumentiert</h3>'+logged.map(s=>`<p>${esc(s.name)} · ${statusLabel(s.status)}</p>`).join(''):''}</section></div><aside><section class="card"><div class="row between"><h2>Wie geht’s dir?</h2><span class="muted">Optional</span></div><form id="checkin"><label class="checkrow"><input type="checkbox" name="illness" ${c.illness?'checked':''}>Erkältung / ungewöhnliche Schlappheit: heute keine Intensität</label><div class="fields">${select('Energie','energy',c.energy||'',[['','Nicht angegeben'],[1,'1 · sehr niedrig'],[2,'2 · niedrig'],[3,'3 · normal'],[4,'4 · gut'],[5,'5 · sehr gut']])}${input('Schlaf · Stunden','sleep',c.sleep,'number','min="0" max="24" step="0.5"')}${input('Zeitbudget · Minuten','time',c.time,'number','min="5" max="240" step="5"')}${input('Körpergewicht · kg (optional)','weight',c.weight,'number','min="20" max="400" step="0.1"')}</div><details><summary>Muskelkater & Beschwerden</summary><div class="fields">${['Beine','Rücken','Brust','Schultern','Arme','Rumpf'].map(k=>select(k,'sore-'+k,c.soreness?.[k]??'',[['','Unbekannt'],[0,'Keiner'],[1,'Leicht'],[2,'Mittel'],[3,'Stark'],[4,'Sehr stark']])).join('')}</div><label>Schmerzen / Beschwerden<textarea name="pain" maxlength="1500" placeholder="Wo und bei welcher Bewegung?">${esc(c.pain||'')}</textarea></label></details></form><div class="${r.pain?'warning':'notice'}"><b>${r.applied==='reduced'?'Reduziert':r.applied==='increased'?'Gesteigert · manuell':'Normal'}${r.override?' · überschrieben':''}</b><p>${r.reasons.map(esc).join(' ')}</p>${r.pain?'<p>Bei stechendem Schmerz abbrechen. Bei akuten schweren Beschwerden Hilfe holen. Keine Diagnose durch diese App.</p>':''}</div>${select('Empfehlung überschreiben','override',c.override||'',[['','Empfehlung verwenden'],['normal','Normal'],['reduced','Reduziert'],['increased','Gesteigert (Extras selbst wählen)']],'id="override"')}<p class="reason">Automatisch gespeichert. Anpassungen gelten für neu gestartete Einheiten; laufende Trainings bleiben nachvollziehbar.</p></section><section class="card"><h3>Noch Zeit nach dem Plan?</h3><p class="muted">Arme sind auch bei Zug- und Druckübungen beteiligt. Im Folgeplan gibt es gezielte Armübungen. Höchstens 2 bis 4 Zusatzsätze, wenn du erholt bist. Mehr Übungen ersetzen keine regelmäßige Ausdauer.</p></section></aside></div>`;}
function statusLabel(s){return ({active:'Läuft',completed:'Abgeschlossen',partial:'Teilweise absolviert',aborted:'Abgebrochen',skipped:'Ausgelassen',pending:'Noch nicht bestätigt',undocumented:'Nicht dokumentiert',done:'Absolviert',replaced:'Ersetzt',planned:'Geplant'})[s]||s;}
const basisLabel=e=>({perHand:'Gewicht pro Hand',total:'Gesamtlast',assistance:'Unterstützung · weniger = schwerer',bodyweight:'Körpergewicht / Variante'})[e.basis];
function exerciseHTML(e,i,s){const finished=['skipped','replaced'].includes(e.status);const done=e.sets.filter(t=>t.status==='done').length;return `<section class="card exercise ${done===e.sets.length?'completed':''}" data-ex="${i}"><div class="row between"><div><span class="eyebrow">${e.extra?'Zusätzlich':String(i+1).padStart(2,'0')} · ${done}/${e.sets.length} Sätze</span><h2>${esc(e.name)}</h2></div><span class="badge">${e.min}–${e.max} ${e.mode==='time'?'Sekunden':e.side?'je Seite':'Wdh.'}</span></div><p class="reason">${esc(basisLabel(e))} · ${esc(e.variant)} · ${esc(e.equipment)}</p>${finished?`<div class="notice">${statusLabel(e.status)}${e.reason?' · '+esc(e.reason):''}</div>`:`<p class="reason">${esc(e.guidance||'Freiwillige Ergänzung. Last und Umfang passend zur verbleibenden Reserve wählen.')}</p>${e.suggestedKg!=null?`<button class="small" data-action="apply-suggestion" data-i="${i}">Vorschlag ${C.fmt(C.fromKg(e.suggestedKg,e.unit))} ${e.unit} übernehmen</button>`:''}${e.sets.map((t,j)=>`<div class="set-grid"><span class="set-number">${j+1}</span>${input(e.mode==='bodyweight'?'Zusatzlast':'Last · '+e.unit,'load',nval(C.fromKg(t.loadKg,e.unit)),'number',`data-i="${i}" data-j="${j}" data-field="load" min="0" max="2000" step="any" placeholder="${e.mode==='bodyweight'?'0':'offen'}"`)}${input(e.mode==='time'?'Sekunden':e.side?'Wdh. links':'Wdh.','reps',t.reps,'number',`data-i="${i}" data-j="${j}" data-field="reps" min="1" max="600" step="1"`)}${input('Reserve','rir',t.rir,'number',`data-i="${i}" data-j="${j}" data-field="rir" min="0" max="10" step="1"`)}<button class="${t.status==='done'?'confirmed':''}" data-action="confirm-set" data-i="${i}" data-j="${j}" aria-label="Satz ${j+1} ${esc(e.name)} ${t.status==='done'?'wieder öffnen':'bestätigen'}">${t.status==='done'?'✓ Fertig':'Bestätigen'}</button>${e.side?`<div></div>${input(e.mode==='time'?'Sekunden rechts':'Wdh. rechts','right',t.right,'number',`data-i="${i}" data-j="${j}" data-field="right" min="1" max="600" step="1"`)}`:''}<label class="checkrow ${e.side?'':'full'}"><input type="checkbox" data-i="${i}" data-j="${j}" data-field="clean" ${t.clean?'checked':''}>Saubere Technik${t.status==='done'?' · bestätigt':''}</label></div>`).join('')}<div class="row"><button class="small" data-action="add-set" data-i="${i}">+ Satz</button><button class="small" data-action="timer" data-seconds="${e.rest}">Pause ${e.rest} s</button><button class="quiet" data-action="skip-ex" data-i="${i}">Auslassen</button><button class="quiet" data-action="replace-ex" data-i="${i}">Ersetzen</button>${e.extra?`<button class="quiet" data-action="remove-extra" data-i="${i}">Zusatzübung entfernen</button>`:''}</div>`}<details><summary>Gerät, Variante & Einheiten${e.guide?' · Anleitung':''}</summary><div class="fields">${select('Anzeigeeinheit','unit',e.unit,['lb','kg'],`data-exfield="unit" data-i="${i}"`)}${input('Gewichtsschritt · '+e.unit,'step',e.step,'number',`data-exfield="step" data-i="${i}" min="0.1" max="100" step="any"`)}${input('Gerät / Gym','equipment',e.equipment,'text',`data-exfield="equipment" data-i="${i}" maxlength="100"`)}${input('Variante / Griff / Auflage','variant',e.variant,'text',`data-exfield="variant" data-i="${i}" maxlength="100"`)}</div><p class="reason">Anderes Gerät oder andere Variante beginnt eine eigene Leistungsserie. Bereits bestätigte Sätze sperren diese Angaben. KG/LB darfst du jederzeit umschalten; Originalwerte bleiben erhalten.</p>${e.guide?`<a href="berias-uebungsuebersicht.html#u${esc(e.guide)}" target="_blank" rel="noopener">Übungsanleitung öffnen ↗</a>`:''}</details></section>`;}
function cardioHTML(c){return `<section class="card"><h2>Ausdauer erfassen</h2><div class="notice">${esc(c.protocol)}<br><b>Geplant: ${c.plannedMinutes} Minuten</b></div><form id="cardio"><div class="fields">${select('Aktivität','activity',c.activity,['Radfahren','Laufen','Gehen','Run-Walk','Sonstiges'])}${input('Gerät / Strecke','device',c.device,'text','maxlength="150"')}${input('Bedingungen','conditions',c.conditions,'text','maxlength="150"')}${input('Dauer gesamt · min','duration',c.duration,'number','min="1" max="1440" step="any"')}${input('Strecke','distance',c.distance,'number','min="0" max="1000" step="any"')}${select('Streckeneinheit','distanceUnit',c.distanceUnit,['mi','km'])}${input('Anstrengung · 1–10','rpe',c.rpe,'number','min="1" max="10" step="1"')}${input('Ø Puls · optional','pulse',c.pulse,'number','min="30" max="250" step="1"')}${input('Steigung % · optional','incline',c.incline,'number','min="0" max="40" step="0.5"')}${input('Gerätetempo · optional','speed',c.speed,'number','min="0" max="100" step="any"')}${select('Tempoeinheit','speedUnit',c.speedUnit,['mph','km/h'])}</div></form><div id="pace" class="notice">${pace(c)}</div><details><summary>Intervalle einzeln dokumentieren</summary><p class="reason">Arbeits- und Pausenzeiten tatsächlich eintragen. Vorgaben werden erst nach deiner Bestätigung als absolviert gewertet.</p>${c.plannedIntervals.length?'<button data-action="copy-intervals">Geplante Intervalle als Eingabe übernehmen</button>':''}<div id="interval-rows">${c.intervals.map((x,i)=>`<div class="fields">${input('Intervall '+(i+1)+' · Arbeit s','workSeconds',x.workSeconds,'number',`data-interval="${i}" min="0" max="3600"`)}${input('Pause danach · s','restSeconds',x.restSeconds,'number',`data-interval="${i}" min="0" max="3600"`)}</div>`).join('')}</div><button class="spaced" data-action="add-interval">+ Intervall</button></details><button class="${c.confirmed?'confirmed':'dark'}" data-action="confirm-cardio">${c.confirmed?'✓ Ausdauer bestätigt':'Ausdauer bestätigen'}</button></section>`;}
function pace(c){const distanceKm=c.distance==null?null:c.distance*(c.distanceUnit==='mi'?C.MI:1);if(!distanceKm||!c.duration)return 'Tempo erscheint nach Dauer und Strecke.';const kmh=distanceKm/(c.duration/60),pk=c.duration/distanceKm,pm=pk*C.MI;const t=x=>{const secs=Math.round(x*60);return `${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;};return `${C.fmt(kmh)} km/h · ${C.fmt(kmh/C.MI)} mph · ${t(pk)} min/km · ${t(pm)} min/mi`;} 
function renderTraining(){const s=active();if(!s)return `<div class="empty card"><span class="eyebrow">Bereit, wenn du es bist</span><h1>Kein Training läuft.</h1><p class="muted">Starte deine geplante Einheit oder erfasse ein freies Training.</p><div class="row" style="justify-content:center"><button class="dark" data-nav="today">Zu Heute</button><button data-action="start" data-key="extra">Freies Training</button></div></div>`;const count=s.exercises.reduce((n,e)=>n+e.sets.filter(t=>t.status==='done').length,0),all=s.exercises.reduce((n,e)=>n+e.sets.length,0);return `<div class="row between"><div><div class="eyebrow">${esc(s.date)} · Woche ${s.week} · ${esc(s.location)}</div><h1>${esc(s.name)}</h1></div><span class="badge green">Laufendes Training</span></div><div class="notice">${esc(s.recommendation.reasons.join(' '))}${s.type==='strength'?` Ziel: ${s.targetRir} Wiederholungen Reserve.`:''}</div><div class="progress-track"><span style="width:${all?count/all*100:0}%"></span></div>${s.cardio?cardioHTML(s.cardio):''}${s.exercises.map((e,i)=>exerciseHTML(e,i,s)).join('')}<div class="card"><div class="row"><button class="dark" data-action="add-ex">+ Übung hinzufügen</button>${!s.cardio?'<button data-action="add-cardio">+ Ausdauer / Aktivität</button>':''}</div><p class="reason">Bizeps, Trizeps, Schultern oder eigene Übung. Ergänzungen werden als Extras gespeichert.</p><label>Notiz zur Einheit<textarea id="session-notes" maxlength="5000">${esc(s.notes)}</textarea></label></div><div class="sticky"><div class="row between"><p>${count} / ${all} Sätze bestätigt <span class="timer" id="timer"></span></p><div class="row"><button class="primary" data-action="finish" data-status="completed">Einheit abschließen</button><button data-action="finish" data-status="partial">Teilweise</button><button data-action="finish" data-status="aborted">Abbrechen</button></div></div></div>`;}
function chart(values,labels){if(values.length<2)return '<div class="empty"><strong>Noch nicht genug Daten</strong><p class="muted">Mindestens zwei vergleichbare Einträge nötig.</p></div>';const max=Math.max(...values,1);return `<div class="chart" role="img" aria-label="${esc(labels.map((x,i)=>x+': '+C.fmt(values[i])).join('; '))}">${values.map((v,i)=>`<div class="bar" style="height:${Math.max(2,v/max*125)}px" title="${esc(labels[i])}: ${C.fmt(v)}"><span>${C.fmt(v)}</span></div>`).join('')}</div><div class="chart-labels"><span>${esc(labels[0])}</span><span>${esc(labels.at(-1))}</span></div>`;}
function renderHistory(){const sessions=state.sessions.filter(s=>s.status!=='active').sort((a,b)=>b.date.localeCompare(a.date));const completed=sessions.filter(s=>s.exercises.some(e=>e.sets.some(t=>t.status==='done'))||s.cardio?.confirmed);const weeks=Array.from({length:4},(_,i)=>{const start=C.addDays(today(),-27+i*7),end=C.addDays(start,6),ss=completed.filter(s=>s.date>=start&&s.date<=end);return {start,count:ss.length,sets:ss.reduce((n,s)=>n+s.exercises.reduce((m,e)=>m+e.sets.filter(t=>t.status==='done').length,0),0),minutes:ss.reduce((n,s)=>n+(s.cardio?.confirmed?s.cardio.duration:0),0)};});const series=new Map();for(const s of completed)for(const e of s.exercises)if(e.sets.some(t=>t.status==='done'))series.set(C.seriesKey(e),e);const key=window.selectedSeries||[...series.keys()][0],ex=series.get(key);let points=[];if(ex)points=completed.slice().reverse().flatMap(s=>s.exercises.filter(e=>C.seriesKey(e)===key).map(e=>({date:s.date,sets:e.sets.filter(t=>t.status==='done')})));const cardioGroups=new Map();for(const s of completed.filter(s=>s.cardio?.confirmed&&s.cardio.distance&&s.cardio.duration&&s.cardio.rpe)){const c=s.cardio,k=[c.activity,c.device,c.conditions,c.rpe,c.incline??'?',c.protocol].join('|');if(!cardioGroups.has(k))cardioGroups.set(k,[]);cardioGroups.get(k).push(s);}const cg=[...cardioGroups.values()].find(g=>g.length>=2);const energies=state.checkins.filter(c=>c.energy!=null).slice(-12);return `<div class="row between"><div><div class="eyebrow">Deine tatsächliche Belastung</div><h1>Verlauf & Fortschritt</h1></div><button data-nav="settings">Exportieren ↗</button></div><div class="grid"><section class="card"><h2>Die letzten vier Wochen</h2>${chart(weeks.map(w=>w.count),weeks.map(w=>w.start))}<p class="reason">Einheiten mit bestätigten Sätzen oder bestätigter Ausdauer. Teiltrainings zählen mit.</p><div class="table-scroll"><table><thead><tr><th>Ab</th><th>Einheiten</th><th>Arbeitssätze</th><th>Cardio min</th></tr></thead><tbody>${weeks.map(w=>`<tr><td>${w.start}</td><td>${w.count}</td><td>${w.sets}</td><td>${C.fmt(w.minutes)}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><h2>Erholung</h2>${chart(energies.map(c=>c.energy),energies.map(c=>c.date))}<p class="reason">Energie 1–5, nur dokumentierte Check-ins. Aus wenigen Daten lassen sich weder Übertraining noch Stärken und Schwächen sicher ableiten.</p></section></div><section class="card"><h2>Übungsleistung</h2>${series.size?select('Vergleichbare Leistungsserie','series',key,[...series].map(([k,e])=>[k,`${e.name} · ${e.variant} · ${e.equipment} · ${basisLabel(e)}`]),'id="history-series"'):''}${chart(points.map(p=>ex?.mode==='bodyweight'?p.sets.reduce((n,t)=>n+(t.reps||0),0):Math.max(...p.sets.map(t=>C.fromKg(t.loadKg,ex.unit)||0))),points.map(p=>p.date))}${ex?`<p class="reason">${ex.mode==='bodyweight'?'Summe bestätigter Wiederholungen':`Höchste bestätigte ${ex.mode==='assistance'?'Unterstützung (weniger ist Fortschritt)':'Last'} in ${ex.unit}`} · ${esc(basisLabel(ex))}. Kein geschätztes Maximalgewicht.</p><div class="table-scroll"><table><thead><tr><th>Datum</th><th>Sätze: Last / Wiederholungen / Reserve</th></tr></thead><tbody>${points.map(p=>`<tr><td>${p.date}</td><td>${p.sets.map(t=>`${C.fmt(C.fromKg(t.loadKg,ex.unit))} ${ex.unit} / ${t.reps}${ex.side?' L, '+t.right+' R':''} ${ex.mode==='time'?'s':'Wdh.'} / ${t.rir??'?'} RIR`).join(' · ')}</td></tr>`).join('')}</tbody></table></div>`:''}</section><section class="card"><h2>Ausdauer bei vergleichbarer Anstrengung</h2>${cg?chart(cg.slice().reverse().map(s=>s.cardio.distance*(s.cardio.distanceUnit==='mi'?C.MI:1)/s.cardio.duration*60),cg.slice().reverse().map(s=>s.date)):'<p class="muted">Noch nicht genug Daten mit gleicher Aktivität, Gerät/Strecke, Bedingungen, Steigung, Protokoll und Anstrengung.</p>'}${cg?`<p class="reason">${esc(cg[0].cardio.activity)} · ${esc(cg[0].cardio.device)} · ${esc(cg[0].cardio.conditions)} · Anstrengung ${cg[0].cardio.rpe}/10. Durchschnitt km/h; subjektive Anstrengung bleibt eine Schätzung.</p>`:''}</section><section class="card"><h2>Trainingstagebuch</h2>${sessions.length?sessions.map(s=>`<details><summary>${esc(s.date)} · ${esc(s.name)} <span class="badge">${statusLabel(s.status)}</span></summary><p class="reason">W${s.week} · ${esc(s.planId)} · ${esc(s.timezone)} · ${esc(s.location)}</p>${s.exercises.map(e=>`<p><b>${esc(e.name)}${e.extra?' + Extra':''}</b> · ${statusLabel(e.status)} · ${e.sets.filter(t=>t.status==='done').length}/${e.sets.length} bestätigt ${e.reason?'· '+esc(e.reason):''}</p>`).join('')}${s.cardio?`<p>Ausdauer ${s.cardio.confirmed?'bestätigt':'nicht bestätigt'}: ${s.cardio.duration??'?'} min · ${s.cardio.distance??'?'} ${s.cardio.distanceUnit} · ${pace(s.cardio)}</p>`:''}<p>${esc(s.notes)}</p><button class="small" data-action="session-detail" data-id="${s.id}">Alle Werte ansehen</button></details>`).join(''):'<p class="muted">Deine ersten Einträge erscheinen hier. Es wurden keine Demo-Daten angelegt.</p>'}</section><section class="card"><h2>Plan & Datenlücken · letzte 28 Tage</h2><details><summary>Geplant gegenüber dokumentiert</summary><ul>${C.calendar(state,C.addDays(today(),-27),today()).filter(x=>x.date>=state.settings.startDate).map(x=>`<li>${x.date} · ${esc(x.name)} · ${esc(x.status)}</li>`).join('')||'<li>Der Plan beginnt gerade erst.</li>'}</ul></details><p class="reason">Ein nicht dokumentierter Tag bedeutet nicht automatisch, dass du nicht trainiert hast. Weitere Aktivitäten und Geräte können fehlen. Mengen und Erholung über mehrere Wochen gemeinsam betrachten.</p></section>`;}
function renderSettings(){return `<section class="card"><span class="eyebrow">Update · 21.10.2026</span><h2>Hybrid-Plan mit festen Mobility-Abenden</h2><p>Neue Planversion mit zwei Krafttagen, dosierter Ausdauer und Mobility Dienstag, Donnerstag und Samstag um 20:30 Uhr. Vor Übernahme ein vollständiges Backup exportieren.</p><button class="dark" data-action="load-review-plan">Neuen Plan prüfen</button><p><a href="review-plan.json" download>Plan als JSON herunterladen</a></p><p>Software-Updates verändern deinen Plan nicht automatisch. Bestehende und laufende Trainings behalten ihre Version.</p></section><section class="card"><h2>Übungen verwalten</h2><p>Fehlerhafte Einträge bearbeiten oder aus der Auswahl löschen. Bereits gespeicherte Trainings bleiben erhalten.</p><button data-action="manage-library">Übungsbibliothek öffnen</button></section><div class="eyebrow">Lokal, ohne Konto</div><h1>Einstellungen & Daten</h1><div class="warning">Deine Daten liegen nur in diesem Browser. Browserdatenlöschung kann sie entfernen. Andere Geräte haben getrennte Daten. Bitte regelmäßig ein vollständiges Backup speichern.</div><div class="grid spaced"><div><section class="card"><h2>Export für deine Auswertung</h2><p>Vollständige Datensätze und ein lesbarer deutscher Bericht. Du entscheidest, ob du sie in Codex oder ChatGPT hochlädst.</p><div class="fields">${input('Von','export-from',C.addDays(today(),-27),'date','id="export-from"')}${input('Bis','export-to',today(),'date','id="export-to"')}</div><div class="row spaced"><button class="dark" data-action="export-four">Letzte 4 Wochen exportieren</button><button data-action="export-range">Gewählten Zeitraum exportieren</button></div><p class="reason">Ein Downloadpaket enthält JSON und Markdown. Browser müssen keine mehreren Downloads erlauben.</p><button data-action="backup">Vollständiges Backup (.json)</button><button class="quiet" data-action="export-plan">Aktuellen Plan exportieren</button></section><section class="card"><h2>Überarbeiteten Plan importieren</h2><p class="reason">Separates Planformat mit Version, neuem Startdatum und Änderungsvorschau. Frühere Trainingseinträge bleiben erhalten.</p><label>Plan-Datei (.json)<input type="file" id="plan-file" accept=".json,application/json"></label><p><a href="FORMAT.md" download>Formatbeschreibung herunterladen</a></p></section><section class="card"><h2>Backup wiederherstellen</h2><p class="reason">Ein vollständiges Backup ersetzt den lokalen Datenbestand erst nach Vorschau und Bestätigung. Vorher wird der aktuelle Stand als Sicherheitsbackup heruntergeladen. Kein Vermischen oder stilles Duplizieren.</p><label>Backup-Datei (.json)<input type="file" id="backup-file" accept=".json,application/json"></label>${storageError?'<button data-action="raw-backup">Unveränderte Browserdaten sichern</button>':''}</section></div><div><section class="card"><h2>Dein Rahmen</h2><form id="settings"><div class="fields">${select('Trainingszeitzone','zone',state.settings.zone,[['America/New_York','Miami · Eastern Time'],['Europe/Berlin','Deutschland']])}${select('Standard für neue Übungen','unit',state.settings.unit,['lb','kg'])}${input('Gym / Trainingsort','location',state.settings.location,'text','maxlength="100"')}${input('Planstart','startDate',state.settings.startDate,'date',state.sessions.length?'disabled':'')}</div><label class="checkrow"><input type="checkbox" name="runReady" ${state.settings.runReady?'checked':''}>30 min locker laufen derzeit gut verträglich</label><label class="checkrow"><input type="checkbox" name="deload" ${state.settings.deload?'checked':''}>Geplante Entlastung in Woche 4 und 8 anwenden</label><p class="reason">Entlastung ist eine anpassbare Planungsregel, kein wissenschaftlich exakt ermittelter Bedarf.</p><label>Ziele<textarea name="goals">${esc(state.profile.goals.join('\n'))}</textarea></label></form><button data-action="persistent">Dauerhafte Browserspeicherung anfragen</button></section><section class="card"><h2>Deutschlandreise</h2><form id="trip-form"><div class="fields">${input('Ankunft','start','','date','required')}${input('Letzter Reisetag','end','','date','required')}</div><label class="checkrow"><input type="checkbox" name="gym">Gym verfügbar</label><button type="submit">Reise speichern</button></form><p class="reason">Erste 48 h locker; ohne Gym Rucksack/Band-Alternativen. Nach mindestens 2 Wochen Reise: 7 Tage reduzierter Wiedereinstieg. Zeitzone oben bewusst umstellen; alte Daten behalten ihre Zeitzone.</p>${state.trips.map((t,i)=>`<p>${t.start} – ${t.end} · ${t.gym?'mit Gym':'ohne Gym'} <button class="small" data-action="remove-trip" data-i="${i}">Entfernen</button></p>`).join('')}</section><section class="card"><h2>Planversionen & Grundlagen</h2>${state.plans.map(p=>`<p><b>${esc(p.name)}</b><br><small>${esc(p.id)} · ab ${p.effectiveFrom}</small></p>`).join('')}<p class="reason">Regelmäßiges Krafttraining großer Muskelgruppen, ohne Pflicht zum Muskelversagen. Konkrete Progression, Entlastung und Reiseanpassungen sind überprüfbare Heuristiken. Keine Diagnose, Erfolgsgarantie oder militärische Validierung.</p><p><a href="https://acsm.org/resistance-training-guidelines-update-2026/" target="_blank" rel="noopener">ACSM 2026 ↗</a> · <a href="https://www.who.int/europe/news-room/fact-sheets/item/physical-activity" target="_blank" rel="noopener">WHO Bewegung ↗</a></p><a href="berias-wochenplan-12-wochen.html" target="_blank" rel="noopener">Trainingswoche & Installation ↗</a></section></div></div>`;}
function startSession(key){if(storageError)return toast('Speichern ist blockiert. Bitte zuerst die Daten prüfen.');if(active())return nav('training');const s=C.buildSession(state,selectedDate,key);state.sessions.push(s);if(save())nav('training');}
function picker(replaceIndex=null){const s=active();const used=[...new Set(state.sessions.flatMap(x=>x.exercises.filter(e=>e.extra).map(e=>e.id)))];const catalog=C.exerciseLibrary(state).sort((a,b)=>Number(used.includes(b.id))-Number(used.includes(a.id)));modal(replaceIndex==null?'Übung hinzufügen':'Übung ersetzen',`<p class="reason">${replaceIndex==null?'Spontane Extras bleiben getrennt vom Grundplan.':'Die ursprüngliche Übung und bereits bestätigte Sätze bleiben erhalten.'}</p><div class="fields">${catalog.map(e=>`<button data-action="pick-ex" data-id="${e.id}" data-replace="${replaceIndex??''}">${esc(e.name)}${used.includes(e.id)?' · zuletzt genutzt':''}</button>`).join('')}</div><details><summary>Eigene Übung</summary><form id="custom-ex" data-replace="${replaceIndex??''}">${input('Name','name','','text','required maxlength="100"')}<div class="fields">${select('Messung','mode','load',[['load','Gewicht + Wiederholungen'],['assistance','Unterstützung'],['bodyweight','Körpergewicht / Band'],['time','Sekunden / Carry']])}${select('Lastbasis','basis','total',[['total','Gesamtlast'],['perHand','Pro Hand'],['bodyweight','Körpergewicht'],['assistance','Unterstützung']])}${input('Sätze','sets',2,'number','required min="1" max="10"')}${input('Ziel von','min',8,'number','required min="1" max="600"')}${input('Ziel bis','max',12,'number','required min="1" max="600"')}</div><label class="checkrow"><input type="checkbox" name="side">Links und rechts separat</label><button type="submit" class="dark">Eigene Übung hinzufügen</button></form></details>`);}
function addExercise(def,replace){const s=active();if(!s)return;if(!def)return toast('Diese Übung ist nicht mehr in der Auswahl.');if(s.exercises.filter(e=>e.extra&&e.status!=='replaced').reduce((n,e)=>n+e.sets.length,0)>=4&&(replace==null||replace===''))return toast('Bereits mindestens 4 Zusatzsätze. Heute beenden oder eine Übung ersetzen, damit Ausdauer und Erholung Platz behalten.');const e=C.newExtra(def,state,s);if(replace!==''&&replace!=null){const old=s.exercises[Number(replace)];old.status='replaced';old.reason='Ersetzt durch '+e.name;old.sets.forEach(t=>{if(t.status==='pending')t.status='skipped';});e.extra=old.extra;e.replaces=old.id;e.planned=old.planned;}s.exercises.push(e);save();dialog.close();render();}
function download(name,text,type='application/json'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
// Small uncompressed ZIP writer: keeps analysis JSON and readable report in one explicit download.
function zip(files){const enc=new TextEncoder();let offset=0;const parts=[],central=[];const u16=(v,n,x)=>v.setUint16(n,x,true),u32=(v,n,x)=>v.setUint32(n,x>>>0,true);function crc(data){let c=0xffffffff;for(const b of data){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0);}return (c^0xffffffff)>>>0;}for(const [name,content]of Object.entries(files)){const n=enc.encode(name),d=enc.encode(content),sum=crc(d),h=new Uint8Array(30+n.length),v=new DataView(h.buffer);u32(v,0,0x04034b50);u16(v,4,20);u16(v,6,0x800);u32(v,14,sum);u32(v,18,d.length);u32(v,22,d.length);u16(v,26,n.length);h.set(n,30);parts.push(h,d);const ch=new Uint8Array(46+n.length),cv=new DataView(ch.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,8,0x800);u32(cv,16,sum);u32(cv,20,d.length);u32(cv,24,d.length);u16(cv,28,n.length);u32(cv,42,offset);ch.set(n,46);central.push(ch);offset+=h.length+d.length;}const size=central.reduce((n,x)=>n+x.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);u32(ev,0,0x06054b50);u16(ev,8,central.length);u16(ev,10,central.length);u32(ev,12,size);u32(ev,16,offset);return new Blob([...parts,...central,end],{type:'application/zip'});}
function analysisExport(from,to){if(!C.validDate(from)||!C.validDate(to)||from>to||C.daysBetween(from,to)>3660)return toast('Bitte einen gültigen Zeitraum bis maximal 10 Jahre wählen.');const d=C.exportData(state,from,to),blob=zip({'trainingsdaten.json':JSON.stringify(d,null,2),'Trainingsbericht.md':C.report(d)});download('BERIAS-Auswertung-'+from+'_'+to+'.zip',blob,'application/zip');toast('Auswertung als ZIP gespeichert.');}
function updateTimer(){const s=active(),el=document.querySelector('#timer');if(!el||!s?.timerEnd)return;const remaining=Math.max(0,Math.ceil((s.timerEnd-Date.now())/1000));el.textContent=remaining?` · Pause ${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`:' · Pause beendet';}
async function handleClick(event){const b=event.target.closest('button,[data-nav]');if(!b)return;if(b.dataset.nav)return nav(b.dataset.nav);if(b.dataset.date){selectedDate=b.dataset.date;return render();}const a=b.dataset.action,s=active(),i=Number(b.dataset.i),j=Number(b.dataset.j),e=s?.exercises[i];try{switch(a){case'close-dialog':dialog.close();break;case'start':startSession(b.dataset.key);break;case'choose-session':{const p=C.activePlan(state,selectedDate);modal('Einheit wählen',`<p>${esc(dateLabel(selectedDate))}. Ersetzt nur den heutigen Kalenderslot. Kein automatisches Nachholen.</p><div class="fields">${p.schedule.map(x=>`<button data-action="choose-key" data-key="${esc(x.key)}">${esc(x.name)}</button>`).join('')}<button data-action="choose-key" data-key="extra">Freies Training</button><button data-action="skip-day">Geplanten Tag auslassen</button></div>`);break;}case'choose-key':state.reschedules[selectedDate]=b.dataset.key;save();dialog.close();render();break;case'skip-day':{const slot=C.planned(state,selectedDate);if(!slot)return toast('An diesem Tag gibt es keinen geplanten Slot.');modal('Tag auslassen',`${input('Optionaler Grund','reason','','text','id="skip-reason" maxlength="500"')}`,`<button class="dark" data-action="confirm-skip-day">Als ausgelassen speichern</button>`);break;}case'confirm-skip-day':{const slot=C.planned(state,selectedDate),x=C.buildSession(state,selectedDate,slot.key);x.notes=dialog.querySelector('#skip-reason').value;x.exercises.forEach(e=>{e.status='skipped';e.reason=x.notes;e.sets.forEach(t=>t.status='skipped');});C.closeSession(x,'skipped');state.sessions.push(x);save();dialog.close();render();break;}case'hold-week':if(state.weekAdjustments.some(x=>x.date===selectedDate&&x.planId===C.activePlan(state,selectedDate).id))return toast('Diese Planwoche wurde bereits ab diesem Tag verlängert.');modal('Planwoche bewusst verlängern','<p>Ab dem ausgewählten Tag verschiebt sich der Wochenfortschritt um 7 Tage. Die Wochentage bleiben gleich, alte Einträge unverändert. Es werden keine verpassten Einheiten hinzugefügt.</p>',`<button class="dark" data-action="confirm-hold">7 Tage verlängern</button>`);break;case'confirm-hold':state.weekAdjustments.push({date:selectedDate,days:7,planId:C.activePlan(state,selectedDate).id,reason:'Manuell verlängert'});save();dialog.close();render();break;case'load-review-plan':{const response=await fetch('./review-plan.json');if(!response.ok)throw Error('Plan konnte nicht geladen werden.');const p=await response.json();if(state.plans.some(x=>x.id===p.id))return toast('Dieser Plan ist bereits vorhanden.');p.effectiveFrom=p.effectiveFrom<today()?today():p.effectiveFrom;importCandidate=C.validatePlan(p);modal('Neuen Plan prüfen',`<h3>${esc(p.name)}</h3>${input('Startdatum','review-start',p.effectiveFrom,'date',`id="review-start" min="${today()}" required`)}<p>Kraft Montag/Mittwoch; Ausdauer Dienstag/Donnerstag/Samstag; Mobility Di 20 min, Do 15 min, Sa 20 min, jeweils 20:30 Uhr. Freitag und Sonntag frei.</p><p>Woche 1 ist ein vorsichtiger Wiedereinstieg. Bei Beschwerden später beginnen. Keine Intervalle nachholen. Alte Trainings bleiben erhalten. Künftige Intervall-Verschiebungen kannst du unter Heute gesondert zurücksetzen.</p><details><summary>Vollständigen Plan ansehen</summary><pre>${esc(JSON.stringify(p,null,2))}</pre></details>`, '<button class="dark" data-action="confirm-review-plan">Plan übernehmen und Sicherheitsbackup speichern</button>');break;}
 case'confirm-review-plan':{const date=dialog.querySelector('#review-start').value;const p=C.validatePlan({...importCandidate,effectiveFrom:date});C.importPlan(C.clone(state),p);download('BERIAS-vor-Planwechsel-'+today()+'.json',JSON.stringify(C.exportData(state,null,null,true),null,2));C.importPlan(state,p);save();dialog.close();selectedDate=date;nav('today');toast('Neue Planversion übernommen.');break;}
 case'mobility-step':C.toggleMobilityStep(state,selectedDate,b.dataset.key,b.dataset.step);save();render();break;
 case'manage-library':manageLibrary();break;
 case'archive-library':C.archiveExercise(state,b.dataset.id);save();manageLibrary();break;
 case'restore-library':C.archiveExercise(state,b.dataset.id,false);save();manageLibrary();break;
 case'edit-library':editLibraryDialog(b.dataset.id);break;
 case'remove-extra':C.removeUnconfirmedExercise(s,i);save();render();break;
 case'recovery-week':state.settings.recoveryUntil=C.addDays(today(),6);save();render();toast('7 Tage konservativer Wiedereinstieg. Keine Intensität bei Beschwerden.');break;
 case'reset-intervals':{const n=C.resetFutureIntervals(state,today());save();render();toast(n+' künftige Intervall-Verschiebungen zurückgesetzt. Historie erhalten.');break;}
 case'add-ex':picker();break;case'replace-ex':picker(i);break;case'pick-ex':addExercise(C.exerciseLibrary(state).find(x=>x.id===b.dataset.id),b.dataset.replace);break;case'add-set':if(e.sets.length>=30)return toast('Maximal 30 Sätze je Übung.');e.sets.push({...C.clone(e.sets.at(-1)),status:'pending',original:null});save();render();break;case'confirm-set':{const t=e.sets[j];if(t.status==='done'){t.status='pending';save();render();break;}if(document.querySelector(`[data-ex="${i}"]`).querySelectorAll('input:invalid').length>0)return toast('Ungültige Zahlen bitte korrigieren.');if(t.reps==null||t.reps<1||t.reps>600||t.rir==null||t.rir<0||t.rir>10||(e.side&&(t.right==null||t.right<1)))return toast('Wiederholungen / Sekunden, Seitenwerte und Reserve prüfen.');if(e.mode!=='bodyweight'&&t.loadKg==null)return toast('Bitte Last bzw. Unterstützung eintragen.');if(t.loadKg==null)t.loadKg=0;t.original=t.original||{value:C.fromKg(t.loadKg,e.unit),unit:e.unit};t.status='done';save();render();break;}case'apply-suggestion':e.sets.filter(t=>t.status==='pending').forEach(t=>{t.loadKg=e.suggestedKg;t.original={value:C.fromKg(t.loadKg,e.unit),unit:e.unit};t.reps=e.min;if(e.side)t.right=e.min;});save();render();break;case'timer':s.timerEnd=Date.now()+Number(b.dataset.seconds)*1000;save();updateTimer();break;case'skip-ex':modal('Übung auslassen',input('Optionaler Grund','reason','','text','id="skip-reason" maxlength="500"'),`<button class="dark" data-action="confirm-skip-ex" data-i="${i}">Auslassen speichern</button>`);break;case'confirm-skip-ex':e.status='skipped';e.reason=dialog.querySelector('#skip-reason').value;e.sets.filter(t=>t.status==='pending').forEach(t=>t.status='skipped');save();dialog.close();render();break;case'finish':modal('Training abschließen?',`<p>${s.exercises.reduce((n,e)=>n+e.sets.filter(t=>t.status==='done').length,0)} bestätigte Sätze. Offene Sätze bleiben „nicht dokumentiert“. Ausgelassene Übungen werden getrennt ausgewiesen.</p><p>Status: <b>${statusLabel(b.dataset.status)}</b></p>`,`<button class="dark" data-action="confirm-finish" data-status="${b.dataset.status}">Jetzt speichern & beenden</button>`);break;case'confirm-finish':C.closeSession(s,b.dataset.status);save();dialog.close();nav('history');toast('Training gespeichert.');break;case'add-cardio':s.cardio={activity:'Gehen',device:state.settings.location,conditions:'Indoor',plannedMinutes:0,protocol:'Zusätzliche Aktivität',duration:null,distance:null,distanceUnit:'mi',rpe:null,pulse:null,incline:null,speed:null,speedUnit:'mph',intervals:[],plannedIntervals:[],confirmed:false};save();render();break;case'copy-intervals':s.cardio.intervals=C.clone(s.cardio.plannedIntervals);s.cardio.confirmed=false;save();render();break;case'add-interval':s.cardio.intervals.push({workSeconds:60,restSeconds:120});s.cardio.confirmed=false;save();render();break;case'confirm-cardio':if(!s.cardio.duration||!s.cardio.rpe)return toast('Bitte Dauer und Anstrengung eintragen.');if(s.cardio.intervals.reduce((n,x)=>n+x.workSeconds+x.restSeconds,0)>s.cardio.duration*60)return toast('Intervallzeiten sind länger als die gesamte Dauer.');s.cardio.confirmed=!s.cardio.confirmed;save();render();break;case'backup':download('BERIAS-Backup-'+today()+'.json',JSON.stringify(C.exportData(state,null,null,true),null,2));break;case'raw-backup':download('BERIAS-Browserdaten-unveraendert.json',localStorage.getItem(KEY)||'null');break;case'export-four':analysisExport(C.addDays(today(),-27),today());break;case'export-range':analysisExport(document.querySelector('#export-from').value,document.querySelector('#export-to').value);break;case'export-plan':download('BERIAS-Plan-v1.json',JSON.stringify(C.activePlan(state,today()),null,2));break;case'confirm-plan':C.importPlan(state,importCandidate);save();dialog.close();render();toast('Neue Planversion gespeichert.');break;case'confirm-restore':{download('BERIAS-Sicherheitsbackup-'+today()+'.json',localStorage.getItem(KEY)||JSON.stringify(state));const restored=C.validateBackup(importCandidate);restored.revision=Math.max(state.revision,restored.revision||0)+1;localStorage.setItem(KEY,JSON.stringify(restored));state=restored;storageError='';selectedDate=today();dialog.close();render();toast('Backup wiederhergestellt.');break;}case'remove-trip':state.trips.splice(i,1);save();render();break;case'persistent':{const persisted=await navigator.storage?.persist?.();toast(persisted?'Dauerhafte Speicherung vom Browser erlaubt. Backup bleibt sinnvoll.':'Browser hat keine dauerhafte Speicherung zugesagt. Bitte Backups behalten.');break;}case'session-detail':{const item=state.sessions.find(x=>x.id===b.dataset.id);modal(esc(item.name),`<pre>${esc(C.report({...C.exportData(state,item.date,item.date),sessions:[item]}))}</pre>`);break;}}}catch(err){toast(err.message);}}
document.addEventListener('click',handleClick);
document.addEventListener('input',event=>{const el=event.target,s=active();if(el.matches('[data-field]')&&s){if(el.type==='number'&&!el.validity.valid)return;const e=s.exercises[Number(el.dataset.i)],t=e.sets[Number(el.dataset.j)],k=el.dataset.field;if(k==='load'){t.loadKg=el.value===''?null:C.kg(Number(el.value),e.unit);t.original=el.value===''?null:{value:Number(el.value),unit:e.unit};}else t[k]=el.type==='checkbox'?el.checked:number(el.value);if(t.status==='done')t.status='pending';save();const b=el.closest('.set-grid').querySelector('button');b.classList.remove('confirmed');b.textContent='Bestätigen';return;}if(el.closest('#checkin')){if(!el.validity.valid)return;let c=state.checkins.find(c=>c.date===selectedDate);if(!c){c={date:selectedDate,timezone:state.settings.zone,soreness:{}};state.checkins.push(c);}if(el.name.startsWith('sore-')){if(el.value==='')delete c.soreness[el.name.slice(5)];else c.soreness[el.name.slice(5)]=Number(el.value);}else c[el.name]=el.type==='checkbox'?el.checked:el.name==='pain'?el.value:number(el.value);if(el.name==='weight'){state.weights=state.weights.filter(w=>w.date!==selectedDate);if(c.weight!=null)state.weights.push({date:selectedDate,kg:c.weight,timezone:state.settings.zone});}save();return;}if(el.id==='session-notes'&&s){s.notes=el.value;save();return;}if(el.closest('#cardio')&&s){if(!el.validity.valid)return;const c=s.cardio;if(el.name==='distanceUnit'&&c.distance!=null){c.distance=el.value==='km'?c.distance*C.MI:c.distance/C.MI;document.querySelector('#cardio [name=distance]').value=nval(c.distance);}if(el.name==='speedUnit'&&c.speed!=null){c.speed=el.value==='km/h'?c.speed*C.MI:c.speed/C.MI;document.querySelector('#cardio [name=speed]').value=nval(c.speed);}c[el.name]=el.type==='number'?number(el.value):el.value;c.confirmed=false;save();document.querySelector('#pace').textContent=pace(c);const b=document.querySelector('[data-action="confirm-cardio"]');b.className='dark';b.textContent='Ausdauer bestätigen';return;}if(el.dataset.interval!=null&&s){if(!el.validity.valid)return;s.cardio.intervals[Number(el.dataset.interval)][el.name]=Number(el.value);s.cardio.confirmed=false;save();return;}if(el.closest('#settings')){if(!el.validity.valid)return;const k=el.name;if(k==='goals')state.profile.goals=el.value.split('\n').filter(Boolean);else if(k==='startDate'){if(!C.validDate(el.value)||state.sessions.length)return;state.settings.startDate=el.value;state.plans[0].effectiveFrom=el.value;}else state.settings[k]=el.type==='checkbox'?el.checked:el.value;save();}});
document.addEventListener('change',async event=>{const el=event.target,s=active();try{if(el.id==='selected-date'){if(C.validDate(el.value)){selectedDate=el.value;render();}return;}if(el.id==='override'){let c=state.checkins.find(c=>c.date===selectedDate);if(!c){c={date:selectedDate,timezone:state.settings.zone,soreness:{}};state.checkins.push(c);}c.override=el.value;save();render();return;}if(el.closest('#checkin')){const open=!!document.querySelector('#checkin details[open]');render();if(open)document.querySelector('#checkin details').open=true;return;}if(el.dataset.exfield&&s){const e=s.exercises[Number(el.dataset.i)],k=el.dataset.exfield;if(k!=='unit'&&e.sets.some(t=>t.status==='done')){toast('Für neue Geräte/Varianten bitte Übung ersetzen; bestätigte Sätze bleiben unverändert.');render();return;}if(!el.validity.valid||!el.value.trim()){render();return;}if(k==='unit')e.step=C.fromKg(C.kg(e.step,e.unit),el.value);e[k]=k==='step'?Number(el.value):el.value;state.preferences[e.id]={unit:e.unit,step:e.step,equipment:e.equipment,variant:e.variant};if(k==='equipment'||k==='variant'){const previous=C.lastExercise(state,e,s.date);const pr=C.progression(previous,e,s.recommendation,s.targetRir);e.guidance=pr.text;e.suggestedKg=pr.suggested??null;e.sets.forEach((t,j)=>{const old=previous?.sets.filter(x=>x.status==='done')[j];t.loadKg=old?.loadKg??null;t.original=null;t.reps=old?.reps??e.min;t.right=e.side?old?.right??e.min:null;t.rir=old?.rir??s.targetRir;});}save();render();return;}if(el.id==='history-series'){window.selectedSeries=el.value;render();return;}if(el.id==='plan-file'||el.id==='backup-file'){const f=el.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('Datei größer als 20 MB.');const parsed=JSON.parse(await f.text());if(el.id==='plan-file'){importCandidate=C.validatePlan(parsed);C.importPlan(C.clone(state),importCandidate);const old=C.activePlan(state,importCandidate.effectiveFrom);const changed=[];for(const k of ['schedule','workouts','easyMinutes','longMinutes','intervals','deloadWeeks','goals'])if(JSON.stringify(old[k])!==JSON.stringify(importCandidate[k]))changed.push(k);modal('Planänderung prüfen',`<p><b>${esc(importCandidate.name)}</b> · ${esc(importCandidate.id)}</p><p>Wirksam ab <b>${importCandidate.effectiveFrom}</b>. Vorheriger Plan: ${esc(old.name)}.</p><p>Geänderte Bereiche: ${esc(changed.join(', ')||'Name / Startdatum / Versions-ID')}</p><details><summary>Vorher / Nachher vollständig ansehen</summary><h3>Vorher</h3><pre>${esc(JSON.stringify(old,null,2))}</pre><h3>Nachher</h3><pre>${esc(JSON.stringify(importCandidate,null,2))}</pre></details><p>Bestehende Trainingsdaten bleiben unverändert. Ein bereits laufendes Training behält seinen Plan.</p>`,`<button class="dark" data-action="confirm-plan">Diesen Plan bestätigen</button>`);}else{importCandidate=C.validateBackup(parsed);modal('Backup prüfen',`<p>${importCandidate.sessions.length} Einheiten, ${importCandidate.plans.length} Planversionen, ${importCandidate.checkins.length} Check-ins.</p><p>Ersetzt den aktuellen Stand (${state.sessions.length} Einheiten). Identische IDs werden nicht angehängt. Ein Sicherheitsbackup wird vorher heruntergeladen.</p>`,`<button class="danger" data-action="confirm-restore">Backup wiederherstellen</button>`);}el.value='';}}catch(err){toast('Import / Änderung abgelehnt: '+err.message);el.value='';}});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));try{if(form.id==='trip-form'){if(!C.validDate(data.start)||!C.validDate(data.end)||data.start>data.end)throw Error('Reisedaten prüfen.');if(state.trips.some(t=>data.start<=t.end&&data.end>=t.start))throw Error('Reise überschneidet sich mit einer vorhandenen Reise.');state.trips.push({id:C.uid(),start:data.start,end:data.end,gym:data.gym==='on'});save();render();}if(form.id==='edit-library-form'){
 const old=C.exerciseLibrary(state,true).find(e=>e.id===form.dataset.id);
 const def={...old,name:data.name.trim(),side:data.side==='on',basis:data.basis};C.editLibrary(state,def);save();manageLibrary();return;
 }if(form.id==='custom-ex'){const e={id:'custom-'+C.uid(),name:data.name.trim(),mode:data.mode,basis:data.mode==='assistance'?'assistance':data.mode==='bodyweight'?'bodyweight':data.basis,sets:Number(data.sets),min:Number(data.min),max:Number(data.max),side:data.side==='on',unit:state.settings.unit,step:state.settings.unit==='lb'?5:2,rest:90,guide:''};C.validateExerciseDefinition(e);addExercise(e,form.dataset.replace);}}catch(e){toast(e.message);}});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'today';render();});
const standalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
const installButton=document.querySelector('#install-button');
function updateInstallButton(){installButton.hidden=standalone();}
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;updateInstallButton();});
window.addEventListener('appinstalled',()=>{installPrompt=null;installButton.hidden=true;toast('BERIAS wurde zum Startbildschirm hinzugefügt.');});
installButton.addEventListener('click',async()=>{if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();const choice=await prompt.userChoice;if(choice?.outcome==='accepted'){installButton.hidden=true;return;}}const isiOS=/iPhone|iPad|iPod/.test(navigator.userAgent);modal('Als App installieren',`<p>${isiOS?'Öffne die Seite in Safari, tippe auf Teilen und wähle „Zum Home-Bildschirm“. Aktiviere „Als Web-App öffnen“ und tippe auf „Hinzufügen“.':'Öffne die Seite in Chrome und wähle im Menü ⋮ „App installieren“ oder „Zum Startbildschirm hinzufügen“.'}</p><p class="reason">Nach dem ersten vollständigen Laden funktionieren Training und Verlauf auch offline. Deine Daten bleiben auf diesem Gerät. Auf dem iPhone kann die installierte App einen eigenen Speicher gegenüber Safari verwenden: Falls du dort schon Einträge hast, vorher ein vollständiges Backup exportieren und in der installierten App wiederherstellen.</p>`);});
updateInstallButton();
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(reg=>{reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)document.querySelector('#update-button').hidden=false;});});return navigator.serviceWorker.ready;}).then(()=>{document.querySelector('#offline').textContent='Offline bereit · nach dem ersten Laden';}).catch(()=>document.querySelector('#offline').textContent='Offline-App noch nicht verfügbar');}
document.querySelector('#update-button').addEventListener('click',()=>location.reload());
window.addEventListener('online',()=>document.querySelector('#offline').textContent='Online · Daten bleiben lokal');window.addEventListener('offline',()=>document.querySelector('#offline').textContent='Offline · Erfassung bleibt verfügbar');
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_training_view',description:'Öffnet Heute, Training oder Verlauf. Liest keine Gesundheitsdaten und startet keine Einheit.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['today','training','history']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['today','training','history'].includes(input.view))throw Error('Ungültige Ansicht');nav(input.view);return {view};}})).catch(()=>{});}catch{}}
render();timerTick=setInterval(updateTimer,1000);

function manageLibrary(){
 const defs=C.exerciseLibrary(state,true);modal('Übungsbibliothek',`<p>Löschen blendet einen Eintrag bei künftiger Auswahl aus. Historische Sätze bleiben nachvollziehbar und können über Wiederherstellen erneut verfügbar werden. Bearbeitete Definitionen gelten erst bei neu hinzugefügten Übungen.</p><div class="fields">${defs.map(e=>`<section class="card"><b>${esc(e.name)}</b><p>${e.side?'Seiten einzeln':'Beidseitig / ein Wert'} · ${esc(basisLabel(e))}</p><button data-action="edit-library" data-id="${e.id}">Bearbeiten</button> <button data-action="${state.preferences[e.id]?.archived?'restore-library':'archive-library'}" data-id="${e.id}">${state.preferences[e.id]?.archived?'Wiederherstellen':'Aus Auswahl löschen'}</button></section>`).join('')}</div>`);
}
function editLibraryDialog(id){const e=C.exerciseLibrary(state,true).find(x=>x.id===id);modal('Übung korrigieren',`<form id="edit-library-form" data-id="${esc(id)}">${input('Name','name',e.name,'text','required maxlength="100"')}${select('Lastbasis','basis',e.basis,[['total','Gesamtlast'],['perHand','Pro Hand'],['bodyweight','Körpergewicht'],['assistance','Unterstützung']])}<label class="checkrow"><input name="side" type="checkbox" ${e.side?'checked':''}>Links und rechts separat</label><p>Alte Trainings werden nicht umgeschrieben. Eine andere Lastbasis oder Seitenmessung beginnt eine getrennte Vergleichsserie.</p><button class="dark">Korrektur speichern</button></form>`);}

function renderToday(){const p=C.activePlan(state,selectedDate);return (p.mobilitySchedule?'':'<section class="card"><h2>Dein neuer Plan ist verfügbar</h2><p>Mobility an drei Abenden, Arme im Kraftplan und behutsame Intervalle. Deine bisherigen Trainings bleiben erhalten.</p><button data-action="load-review-plan">Neuen Plan prüfen</button></section>')+renderTodayBase()+renderMobility(true);}
function renderMobility(compact=false){
 const date=selectedDate,plan=C.activePlan(state,date),v=C.mobilityForDate(state,date);
 const monday=C.addDays(date,-((new Date(date+'T12:00:00Z').getUTCDay()+6)%7));
 const header=compact?'':`<div class="eyebrow">Beweglichkeit und aktive Kontrolle</div><h1>Mobility am Abend</h1>${input('Mobility-Tag','date',date,'date','id="selected-date"')}<div class="fields">${(plan.mobilitySchedule||[]).map(x=>{const d=C.addDays(monday,x.day===0?6:x.day-1);return `<button data-date="${d}">${esc(dateLabel(d))} · ${x.time}<br>${esc(x.name)}</button>`}).join('')}</div>`;
 if(!plan.mobilitySchedule)return header+'<section class="card"><h2>Mobility fest einplanen</h2><p>Der bisherige Plan enthält noch keine Abendblöcke.</p><button data-nav="settings">Neuen Plan in Einstellungen prüfen</button></section>';
 if(!v)return header+'<section class="card"><h2>Heute kein fester Mobility-Termin</h2><p>Freitag und Sonntag bleiben frei. Montag/Mittwoch bei Bedarf fünf Minuten angenehm bewegen.</p></section>';
 return header+`<section class="card"><div class="row between"><div><span class="eyebrow">${date} · ${v.time} · etwa ${v.minutes} Minuten</span><h2>${esc(v.name)}</h2></div><span class="badge">${v.log?.done?'Erledigt':'Leicht · 2 bis 4/10'}</span></div><p class="reason">Erst angenehm aufwärmen. Sanfter Zug ohne Schmerz, keine Ermüdungsprüfung. Bei Schlappheit nur 5 bis 10 Minuten.</p><ul class="list">${v.exercises.map(e=>`<li><div><b>${esc(e.name)}</b><p>${esc(e.dose)}</p><p class="reason">${esc(e.cue)}</p></div><button aria-pressed="${!!v.log?.steps[e.id]}" aria-label="${esc(e.name)} als ${v.log?.steps[e.id]?'offen':'erledigt'} markieren" data-action="mobility-step" data-key="${v.key}" data-step="${e.id}">${v.log?.steps[e.id]?'✓ Erledigt':'Abhaken'}</button></li>`).join('')}</ul><details><summary>Umfang und Fortschritt</summary><p>${esc(v.notes)}</p><p>Höhe beim Beinheben nur steigern, wenn Becken und Oberkörper ruhig bleiben. Hüfthöhe ist ein späteres Ziel. Vergleiche unter denselben Bedingungen nach vier Wochen.</p></details></section>`;
}
